INSERT INTO public_question_repository (custom_id,course_tags,subject,chapter,topic,difficulty,is_pyq,pyq_year,text,option_a,option_b,option_c,option_d,correct_answer,explanation,image_path,marks,created_at) VALUES
('12-M2B-CR-0001','TS-Inter-2,MPC,JEE','Mathematics','Circle','Equation','Easy',0,NULL,'Standard equation of circle with center (h,k) and radius r is','(x−h)²+(y−k)²=r²','x²+y²=r²','(x+h)²+(y+k)²=r²','x²−y²=r²','A','Circle: locus of points at distance r from center.',NULL,1,NOW()),
('12-M2B-CR-0002','TS-Inter-2,MPC,JEE','Mathematics','Circle','General','Medium',0,NULL,'General equation x²+y²+2gx+2fy+c=0 represents circle with center','(−g,−f)','(g,f)','(−f,−g)','(2g,2f)','A','Center = (−g,−f), radius = √(g²+f²−c).',NULL,1,NOW()),
('12-M2B-CR-0003','TS-Inter-2,MPC,JEE','Mathematics','Circle','Radius','Medium',0,NULL,'Radius of circle x²+y²+2gx+2fy+c=0 is','√(g²+f²−c)','g²+f²−c','√(g²+f²+c)','g+f−c','A','Must have g²+f²−c > 0 for real circle.',NULL,1,NOW()),
('12-M2B-CR-0004','TS-Inter-2,MPC,JEE','Mathematics','Circle','Origin','Easy',0,NULL,'Circle centered at origin with radius 5 is','x²+y²=25','x²+y²=5','x²−y²=25','(x−5)²+y²=25','A','h=0, k=0, r=5.',NULL,1,NOW()),
('12-M2B-CR-0005','TS-Inter-2,MPC,JEE','Mathematics','Circle','Tangent Length','Medium',1,2019,'Length of tangent from point (x₁,y₁) to circle x²+y²+2gx+2fy+c=0 is','√(x₁²+y₁²+2gx₁+2fy₁+c)','x₁²+y₁²+c','0','√(g²+f²)','A','Substitute point in circle equation under square root.',NULL,1,NOW()),
('12-M2B-CR-0006','TS-Inter-2,MPC,JEE','Mathematics','Circle','Tangent Eqn','Medium',0,NULL,'Equation of tangent to circle x²+y²=r² at point (x₁,y₁) is','xx₁+yy₁=r²','y−y₁=m(x−x₁)','x/x₁+y/y₁=1','xx₁−yy₁=r²','A','Replace x² by xx₁, y² by yy₁.',NULL,1,NOW()),
('12-M2B-CR-0007','TS-Inter-2,MPC,JEE','Mathematics','Circle','Normal','Medium',0,NULL,'Normal to a circle always passes through','Center of the circle','Origin','Tangent point only','Infinity','A','Normal is perpendicular to tangent at point of contact.',NULL,1,NOW()),
('12-M2B-CR-0008','TS-Inter-2,MPC,JEE','Mathematics','Circle','Condition','Hard',0,NULL,'Line y=mx+c is tangent to x²+y²=r² when','c²=r²(1+m²)','c=r','c²=r²m²','c=rm','A','Distance from center to line = radius.',NULL,1,NOW()),
('12-M2B-CR-0009','TS-Inter-2,MPC,JEE','Mathematics','Circle','Power','Hard',0,NULL,'Power of a point P(x₁,y₁) w.r.t. circle S=0 is','S₁₁ = x₁²+y₁²+2gx₁+2fy₁+c','0','r²','g²+f²','A','Positive outside, zero on, negative inside circle.',NULL,1,NOW()),
('12-M2B-CR-0010','TS-Inter-2,MPC,JEE','Mathematics','Circle','Chord Contact','Hard',1,2020,'Equation of chord of contact from external point (x₁,y₁) to x²+y²=r² is','xx₁+yy₁=r²','x+y=r','x₁y₁=r²','xx₁−yy₁=0','A','Same form as tangent equation.',NULL,1,NOW()),
('12-M2B-CR-0011','TS-Inter-2,MPC,JEE','Mathematics','Circle','Diameter','Easy',0,NULL,'If (x₁,y₁) and (x₂,y₂) are endpoints of diameter, circle equation is','(x−x₁)(x−x₂)+(y−y₁)(y−y₂)=0','x²+y²=r²','(x−x₁)²+(y−y₁)²=r²','x+y=x₁+y₂','A','Diameter form of circle equation.',NULL,1,NOW()),
('12-M2B-CR-0012','TS-Inter-2,MPC,JEE','Mathematics','Circle','Parametric','Medium',0,NULL,'Parametric equations of circle x²+y²=r² are','x=rcosθ, y=rsinθ','x=rθ, y=rθ','x=r, y=r','x=cosθ, y=sinθ','A','θ is the parameter (angle).',NULL,1,NOW()),
('12-M2B-CR-0013','TS-Inter-2,MPC,JEE','Mathematics','Circle','Intercept','Medium',0,NULL,'Length of x-intercept of circle x²+y²+2gx+2fy+c=0 is','2√(g²−c)','2g','g²−c','2√(f²−c)','A','Put y=0, find difference of x-roots.',NULL,1,NOW()),
('12-M2B-CR-0014','TS-Inter-2,MPC,JEE','Mathematics','Circle','Position','Easy',0,NULL,'Point P lies inside circle S=0 when','S₁₁ < 0','S₁₁ > 0','S₁₁ = 0','S₁₁ = r','A','Negative power means inside.',NULL,1,NOW()),
('12-M2B-CR-0015','TS-Inter-2,MPC,JEE','Mathematics','Circle','Position2','Easy',0,NULL,'Point P lies on circle S=0 when','S₁₁ = 0','S₁₁ > 0','S₁₁ < 0','S₁₁ = 1','A','Zero power means on the circle.',NULL,1,NOW()),
('12-M2B-CR-0016','TS-Inter-2,MPC,JEE','Mathematics','Circle','Pair Tangent','Hard',1,2021,'Equation of pair of tangents from (x₁,y₁) to S=0 is','S₁₁·S = S₁²','S·S₁₁=0','S₁=0','S=S₁₁','A','Combined equation of both tangent lines.',NULL,1,NOW()),
('12-M2B-CR-0017','TS-Inter-2,MPC,JEE','Mathematics','Circle','Pole Polar','Hard',0,NULL,'Polar of point (x₁,y₁) w.r.t. x²+y²=r² is','xx₁+yy₁=r²','x=x₁','y=y₁','x₁y₁=r²','A','Pole-polar relationship.',NULL,1,NOW()),
('12-M2B-CR-0018','TS-Inter-2,MPC,JEE','Mathematics','Circle','Chord Mid','Hard',0,NULL,'Equation of chord of x²+y²=r² with midpoint (h,k) is','hx+ky=h²+k²','x+y=h+k','hx−ky=0','x/h+y/k=1','A','T = S₁₁ where T is tangent form at midpoint.',NULL,1,NOW()),
('12-M2B-CR-0019','TS-Inter-2,MPC,JEE','Mathematics','Circle','Concentric','Easy',0,NULL,'Two circles with same center are called','Concentric','Orthogonal','Touching','Intersecting','A','Same center, different radii.',NULL,1,NOW()),
('12-M2B-CR-0020','TS-Inter-2,MPC,JEE','Mathematics','Circle','Example','Easy',0,NULL,'Center and radius of x²+y²−4x+6y−12=0 are','(2,−3) and 5','(−2,3) and 5','(4,−6) and 12','(2,3) and 25','A','g=−2, f=3. Center (2,−3). r=√(4+9+12)=5.',NULL,1,NOW()),
('12-M2B-CR-0021','TS-Inter-2,MPC,JEE','Mathematics','Circle','Two Tangent','Medium',0,NULL,'Number of tangents from external point to a circle is','2','1','0','Infinite','A','Two tangent lines from any external point.',NULL,1,NOW()),
('12-M2B-CR-0022','TS-Inter-2,MPC,JEE','Mathematics','Circle','Angle','Hard',0,NULL,'Angle between two tangents from (x₁,y₁) to x²+y²=r² uses','tan(θ/2) = r/√(S₁₁)','θ=90° always','θ=0°','θ=180°','A','S₁₁ is power of the point.',NULL,1,NOW()),
('12-M2B-CR-0023','TS-Inter-2,MPC,JEE','Mathematics','Circle','Common Chord','Medium',0,NULL,'Common chord of two intersecting circles S₁=0, S₂=0 is','S₁−S₂=0','S₁+S₂=0','S₁·S₂=0','S₁/S₂=0','A','Radical axis equation.',NULL,1,NOW()),
('12-M2B-CR-0024','TS-Inter-2,MPC,JEE','Mathematics','Circle','Touching','Medium',1,2020,'Two circles touch externally when distance between centers equals','r₁+r₂','|r₁−r₂|','r₁r₂','0','A','External tangency: d = r₁+r₂.',NULL,1,NOW()),
('12-M2B-CR-0025','TS-Inter-2,MPC,JEE','Mathematics','Circle','Internal','Medium',0,NULL,'Two circles touch internally when distance between centers equals','|r₁−r₂|','r₁+r₂','0','r₁r₂','A','Internal tangency: d = |r₁−r₂|.',NULL,1,NOW()),
('12-M2B-CR-0026','TS-Inter-2,MPC,JEE','Mathematics','Circle','Area','Easy',0,NULL,'Area of circle with radius r is','πr²','2πr','πr','2r²','A','Circumference = 2πr, Area = πr².',NULL,1,NOW()),
('12-M2B-CR-0027','TS-Inter-2,MPC,JEE','Mathematics','Circle','Slope Tangent','Medium',0,NULL,'Tangent to x²+y²=r² with slope m is','y=mx±r√(1+m²)','y=mx+r','y=mx','y=mx+r/m','A','Two tangent lines with given slope.',NULL,1,NOW()),
('12-M2B-CR-0028','TS-Inter-2,MPC,JEE','Mathematics','Circle','Family','Hard',0,NULL,'Family of circles through intersection of S₁=0 and S₂=0 is','S₁+λS₂=0','S₁S₂=0','S₁−S₂=λ','λS₁=S₂','A','λ is parameter giving different circles.',NULL,1,NOW()),
('12-M2B-CR-0029','TS-Inter-2,MPC,JEE','Mathematics','Circle','Condition Real','Easy',0,NULL,'x²+y²+2gx+2fy+c=0 represents real circle when','g²+f²−c > 0','g²+f²−c = 0','g²+f²−c < 0','c = 0','A','Radius must be positive.',NULL,1,NOW()),
('12-M2B-CR-0030','TS-Inter-2,MPC,JEE','Mathematics','Circle','Coaxial','Hard',1,2021,'Circles having same radical axis are called','Coaxial circles','Concentric','Orthogonal','Tangent circles','A','System of coaxial circles share radical axis.',NULL,1,NOW());
INSERT INTO public_question_repository (custom_id,course_tags,subject,chapter,topic,difficulty,is_pyq,pyq_year,text,option_a,option_b,option_c,option_d,correct_answer,explanation,image_path,marks,created_at) VALUES
('12-M2B-SC-0001','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Radical Axis','Medium',0,NULL,'Radical axis of two circles S₁=0, S₂=0 is','S₁−S₂=0','S₁+S₂=0','S₁·S₂=0','S₁/S₂=1','A','Locus of points with equal power w.r.t. both circles.',NULL,1,NOW()),
('12-M2B-SC-0002','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Perpendicular','Medium',0,NULL,'Radical axis is always perpendicular to','Line joining centers of two circles','Tangent','x-axis','y-axis','A','Radical axis ⊥ line of centers.',NULL,1,NOW()),
('12-M2B-SC-0003','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Orthogonal','Hard',0,NULL,'Two circles x²+y²+2g₁x+2f₁y+c₁=0 and x²+y²+2g₂x+2f₂y+c₂=0 are orthogonal when','2g₁g₂+2f₁f₂=c₁+c₂','g₁g₂+f₁f₂=0','c₁=c₂','g₁=g₂','A','Condition for circles cutting at right angles.',NULL,1,NOW()),
('12-M2B-SC-0004','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Orthogonal Def','Medium',0,NULL,'Two circles are orthogonal if they intersect at','90° angle','0°','180°','45°','A','Tangents at intersection point are perpendicular.',NULL,1,NOW()),
('12-M2B-SC-0005','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Radical Center','Hard',1,2019,'Radical center of three circles is the point where','All three radical axes meet','Centers meet','Tangents meet','Normals meet','A','Common point of three pairwise radical axes.',NULL,1,NOW()),
('12-M2B-SC-0006','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Coaxial','Medium',0,NULL,'A system of coaxial circles has','Common radical axis','Common center','Same radius','No intersection','A','All pairs share the same radical axis.',NULL,1,NOW()),
('12-M2B-SC-0007','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Limiting Pt','Hard',0,NULL,'Limiting points of a coaxial system are','Point circles (radius = 0) in the system','Largest circles','Centers','Intersections','A','Degenerate circles with zero radius.',NULL,1,NOW()),
('12-M2B-SC-0008','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Common Tangent','Medium',0,NULL,'Maximum number of common tangents to two non-intersecting external circles is','4','2','3','1','A','2 direct + 2 transverse = 4.',NULL,1,NOW()),
('12-M2B-SC-0009','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Tangent Touch','Medium',0,NULL,'Number of common tangents when two circles touch externally is','3','4','2','1','A','2 direct + 1 common tangent at point of contact.',NULL,1,NOW()),
('12-M2B-SC-0010','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Intersecting','Medium',1,2020,'Number of common tangents to two intersecting circles is','2','4','3','0','A','Only 2 direct common tangents.',NULL,1,NOW()),
('12-M2B-SC-0011','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Internal Touch','Medium',0,NULL,'Number of common tangents when circles touch internally is','1','2','3','4','A','Only 1 common tangent at point of contact.',NULL,1,NOW()),
('12-M2B-SC-0012','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Contained','Easy',0,NULL,'If one circle lies entirely inside another (no touch), common tangents = ','0','1','2','4','A','No common tangent possible.',NULL,1,NOW()),
('12-M2B-SC-0013','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Angle Intersect','Hard',0,NULL,'Angle of intersection of two circles with radii r₁,r₂ and center distance d: cosθ =','(d²−r₁²−r₂²)/(2r₁r₂)','(r₁²+r₂²−d²)/(2r₁r₂)','d/(r₁+r₂)','r₁r₂/d²','B','Using cosine rule in triangle formed by radii and line of centers.',NULL,1,NOW()),
('12-M2B-SC-0014','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Power Equal','Medium',0,NULL,'On the radical axis, power of a point w.r.t. both circles is','Equal','Zero','Maximum','Minimum','A','Definition of radical axis.',NULL,1,NOW()),
('12-M2B-SC-0015','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Radical Perp','Hard',0,NULL,'If circles are concentric, radical axis','Does not exist','Is a point','Is x-axis','Is the center','A','Same center means S₁−S₂ is a constant, no locus.',NULL,1,NOW()),
('12-M2B-SC-0016','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Direct CT','Medium',1,2021,'Direct common tangents of two circles divide line segment joining centers','Externally in ratio r₁:r₂','Internally','Equally','Not at all','A','External division for direct tangents.',NULL,1,NOW()),
('12-M2B-SC-0017','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Transverse CT','Medium',0,NULL,'Transverse common tangents divide line joining centers','Internally in ratio r₁:r₂','Externally','Equally','At midpoint always','A','Internal division for transverse tangents.',NULL,1,NOW()),
('12-M2B-SC-0018','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Family','Hard',0,NULL,'S₁+λS₂=0 represents family of circles passing through','Intersection points of S₁ and S₂','Centers','Origin','No fixed points','A','For all λ, circles pass through common points.',NULL,1,NOW()),
('12-M2B-SC-0019','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Coaxial Eqn','Hard',0,NULL,'Coaxial system with S=0 as member and L=0 as radical axis is','S+λL=0','S·L=0','S−L=λ','λS=L','A','λ parameter generates all circles in system.',NULL,1,NOW()),
('12-M2B-SC-0020','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Orthog Coaxial','Hard',0,NULL,'Orthogonal system to a coaxial system is also','Coaxial','Concentric','Random','Not a system','A','Orthogonal trajectories of coaxial circles form another coaxial system.',NULL,1,NOW()),
('12-M2B-SC-0021','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Example','Medium',0,NULL,'Radical axis of x²+y²−4x=0 and x²+y²+2x=0 is','−6x=0 i.e. x=0 (y-axis)','x=1','y=0','x+y=0','A','S₁−S₂: −4x−2x=0, −6x=0, x=0.',NULL,1,NOW()),
('12-M2B-SC-0022','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Length CT','Hard',0,NULL,'Length of direct common tangent between circles with radii r₁,r₂ and center distance d is','√(d²−(r₁−r₂)²)','√(d²−(r₁+r₂)²)','d−r₁−r₂','d','A','For external circles.',NULL,1,NOW()),
('12-M2B-SC-0023','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Length TCT','Hard',1,2020,'Length of transverse common tangent is','√(d²−(r₁+r₂)²)','√(d²−(r₁−r₂)²)','d−r₁+r₂','d','A','For external non-intersecting circles.',NULL,1,NOW()),
('12-M2B-SC-0024','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Condition Orth','Medium',0,NULL,'For orthogonality of two circles, the angle of intersection is','90°','0°','180°','45°','A','Tangents at intersection are perpendicular.',NULL,1,NOW()),
('12-M2B-SC-0025','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Radical Property','Medium',0,NULL,'Tangent lengths from any point on radical axis to both circles are','Equal','Zero','Unequal','Infinite','A','Equal power means equal tangent lengths.',NULL,1,NOW()),
('12-M2B-SC-0026','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Three Circles','Hard',0,NULL,'Three circles taken pairwise give how many radical axes?','3','1','6','2','A','3 pairs = 3 radical axes, concurrent at radical center.',NULL,1,NOW()),
('12-M2B-SC-0027','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Determine','Easy',0,NULL,'To uniquely determine a circle, we need','3 conditions (3 unknowns g,f,c)','1 condition','2 conditions','4 conditions','A','General equation has 3 unknowns.',NULL,1,NOW()),
('12-M2B-SC-0028','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Through 3 Pts','Medium',0,NULL,'Circle through 3 non-collinear points is','Unique (exactly one)','Not possible','Infinitely many','Two circles','A','3 points determine unique circle.',NULL,1,NOW()),
('12-M2B-SC-0029','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Intersection','Medium',1,2021,'Two distinct circles can intersect in at most','2 points','1 point','3 points','4 points','A','A line (radical axis) meets circle in at most 2 points.',NULL,1,NOW()),
('12-M2B-SC-0030','TS-Inter-2,MPC,JEE','Mathematics','System of Circles','Limiting Type','Hard',0,NULL,'In a coaxial system with intersecting type, limiting points are','Imaginary','Real','At infinity','At origin','A','Intersecting type has imaginary limiting points.',NULL,1,NOW());
