('12-M2B-PA-0001','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Definition','Easy',0,NULL,'A parabola is the locus of a point equidistant from','A fixed point (focus) and a fixed line (directrix)','Two fixed points','A fixed point only','Two fixed lines','A','Eccentricity e = 1.',NULL,1,NOW()),
('12-M2B-PA-0002','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Standard','Easy',0,NULL,'Standard equation of parabola opening rightward is','y²=4ax','x²=4ay','y²=−4ax','x²=−4ay','A','Focus (a,0), directrix x=−a.',NULL,1,NOW()),
('12-M2B-PA-0003','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Focus','Medium',0,NULL,'Focus of y²=12x is','(3,0)','(0,3)','(12,0)','(6,0)','A','4a=12, a=3. Focus at (a,0)=(3,0).',NULL,1,NOW()),
('12-M2B-PA-0004','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Directrix','Medium',0,NULL,'Directrix of y²=12x is','x=−3','x=3','y=−3','y=3','A','Directrix: x=−a=−3.',NULL,1,NOW()),
('12-M2B-PA-0005','TS-Inter-2,MPC,JEE','Mathematics','Parabola','LR','Medium',1,2019,'Length of latus rectum of y²=4ax is','4a','2a','a','8a','A','Chord through focus perpendicular to axis.',NULL,1,NOW()),
('12-M2B-PA-0006','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Vertex','Easy',0,NULL,'Vertex of y²=4ax is','(0,0) origin','(a,0)','(0,a)','(−a,0)','A','Vertex is midpoint of focus and directrix foot.',NULL,1,NOW()),
('12-M2B-PA-0007','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Parametric','Medium',0,NULL,'Parametric equations of y²=4ax are','x=at², y=2at','x=acosθ, y=bsinθ','x=t, y=t²','x=2at, y=at²','A','Parameter t gives all points on parabola.',NULL,1,NOW()),
('12-M2B-PA-0008','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Tangent','Hard',0,NULL,'Equation of tangent to y²=4ax at (at²,2at) is','ty=x+at²','y=tx+a','ty=x−at²','y=x/t+at','A','Replace: yy₁=2a(x+x₁) gives ty=x+at².',NULL,1,NOW()),
('12-M2B-PA-0009','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Tangent Slope','Hard',0,NULL,'Tangent to y²=4ax with slope m is','y=mx+a/m','y=mx+am','y=mx−a/m','y=mx','A','Condition: c=a/m for tangency.',NULL,1,NOW()),
('12-M2B-PA-0010','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Normal','Hard',1,2020,'Normal to y²=4ax at (at²,2at) is','y+tx=2at+at³','y−tx=2at','y=−tx+2at','ty+x=at²','A','Slope of normal = −t.',NULL,1,NOW()),
('12-M2B-PA-0011','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Chord','Medium',0,NULL,'Equation of chord joining (at₁²,2at₁) and (at₂²,2at₂) on y²=4ax is','y(t₁+t₂)=2x+2at₁t₂','y=x(t₁+t₂)','t₁t₂y=2x','y=2x/(t₁+t₂)','A','Two-point form simplified.',NULL,1,NOW()),
('12-M2B-PA-0012','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Focal Chord','Hard',0,NULL,'For focal chord of y²=4ax, t₁t₂ = ','−1','1','0','a','A','Chord through focus: product of parameters = −1.',NULL,1,NOW()),
('12-M2B-PA-0013','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Eccentricity','Easy',0,NULL,'Eccentricity of parabola is','1','0','< 1','> 1','A','e = 1 for all parabolas.',NULL,1,NOW()),
('12-M2B-PA-0014','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Downward','Easy',0,NULL,'x²=−4ay represents parabola opening','Downward','Upward','Right','Left','A','Negative coefficient, x² form opens down.',NULL,1,NOW()),
('12-M2B-PA-0015','TS-Inter-2,MPC,JEE','Mathematics','Parabola','Left','Easy',0,NULL,'y²=−4ax represents parabola opening','Left','Right','Up','Down','A','Negative coefficient, y² form opens left.',NULL,1,NOW()),
